use infinite_core::*;use std::num::NonZeroU32;
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}
fn view()->ViewRect{ViewRect{min:GridPosition{x:-1000,y:-1000},max:GridPosition{x:1000,y:1000}}}
fn setup()->(World,[EntityId;2],CombatFrame,SpatialFrame,CombatConnections,ConnectionId){let mut w=World::default();let a=w.spawn(GridPosition::default()).unwrap();let b=w.spawn(GridPosition{x:16,y:0}).unwrap();for e in[a,b]{w.configure_health(e,100,n(100)).unwrap();}let mut net=CombatConnections::with_window(10,NetworkConfig{connections:2,retry_ms:10,ack_timeout_ms:100,combat:CombatSyncConfig{pending_events:64,events_per_packet:1},..NetworkConfig::default()},4).unwrap();let id=net.connect().unwrap();net.set_motion_view(id,view()).unwrap();(w,[a,b],CombatFrame::new(n(64)),SpatialFrame::new(n(64)),net,id)}
fn capture(w:&mut World,e:[EntityId;2],c:&mut CombatFrame,f:&mut SpatialFrame,net:&mut CombatConnections,id:ConnectionId,tick:u64){w.advance_tick().unwrap();w.set_position(e[0],GridPosition{x:tick as i32*3,y:0}).unwrap();w.apply_damage(e[1],1).unwrap();c.capture(w,&[CombatEvent{attacker:e[0],target:e[1],kind:CombatEventKind::Ended(CombatEndReason::TargetGone)}]).unwrap();f.capture(w).unwrap();net.observe(id,c,view()).unwrap();}
fn poll(net:&mut CombatConnections,f:&SpatialFrame,now:u64,limit:usize,bytes:&mut Vec<u8>)->Vec<Vec<u8>>{let mut b=NetworkBudget{work:1,bytes:limit};let mut notices=Vec::new();let r=net.poll_with_motion(now,f,&mut b,&mut notices,|_,part|{let n=part.len().min(3);bytes.extend_from_slice(&part[..n]);WriteProgress::Written(n)}).unwrap();assert_eq!(r.visited+b.work,1);assert_eq!(r.bytes+b.bytes,limit);assert!(notices.is_empty());let mut packets=Vec::new();loop{if bytes.len()<4{break;}let len=u32::from_le_bytes(bytes[..4].try_into().unwrap())as usize;assert!(len<=MAX_COMBAT_SYNC_PACKET_BYTES.max(MAX_SYNC_PACKET_BYTES));if bytes.len()<len+4{break;}packets.push(bytes[4..len+4].to_vec());bytes.drain(..len+4);}packets}
fn receive(net:&mut CombatConnections,id:ConnectionId,packets:Vec<Vec<u8>>,motion:&mut Replica,combat:&mut CombatReplica,events:&mut Vec<CombatFeedback>)->Vec<[u8;20]>{let mut acks=Vec::new();for packet in packets{let ack=if packet.starts_with(b"IS"){motion.apply(&packet).unwrap().acknowledgement()}else{let r=combat.apply(&packet).unwrap();events.extend(combat.drain_feedback());r.acknowledgement()};net.acknowledge(id,&ack).unwrap();acks.push(ack);}acks}
fn drained(net:&CombatConnections,id:ConnectionId)->bool{let s=net.status(id).unwrap();s.queued_events==0&&s.pending_bytes==0&&net.motion_status(id).unwrap().unwrap().pending_bytes==0}

#[test]
fn tiny_shared_budget_never_interleaves_frames_and_both_channels_converge(){let(mut w,e,mut c,mut f,mut net,id)=setup();for tick in 1..=8{capture(&mut w,e,&mut c,&mut f,&mut net,id,tick);}let(mut motion,mut combat)=(Replica::new(10),CombatReplica::new_windowed(10));let mut bytes=Vec::new();let mut kinds=Vec::new();let mut events=Vec::new();for _ in 0..10000{let packets=poll(&mut net,&f,0,1,&mut bytes);kinds.extend(packets.iter().map(|p|p[..2].to_vec()));receive(&mut net,id,packets,&mut motion,&mut combat,&mut events);if drained(&net,id)&&motion.sequence()>0{break;}}assert!(drained(&net,id));assert!(bytes.is_empty());assert_eq!(&kinds[..2],&[b"IC".to_vec(),b"IS".to_vec()]);assert_eq!(events.iter().map(|e|e.tick.0).collect::<Vec<_>>(),(1..=8).collect::<Vec<_>>());assert_eq!(motion.states(),f.visible(view()).unwrap());assert_eq!(combat.states().iter().find(|s|s.entity==e[1]).unwrap().health.unwrap().current,92);}

#[test]
fn movement_ack_wait_coalesces_state_without_holding_combat_events(){let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id,1);let mut bytes=Vec::new();let(mut motion,mut combat)=(Replica::new(10),CombatReplica::new_windowed(10));let mut held=None;let mut events=Vec::new();for _ in 0..1000{for p in poll(&mut net,&f,0,32,&mut bytes){if p.starts_with(b"IS"){held=Some(motion.apply(&p).unwrap().acknowledgement());}else{receive(&mut net,id,vec![p],&mut motion,&mut combat,&mut events);}}if held.is_some()&&net.status(id).unwrap().queued_events==0{break;}}assert!(held.is_some());for tick in 2..=12{capture(&mut w,e,&mut c,&mut f,&mut net,id,tick);}for _ in 0..1000{let p=poll(&mut net,&f,0,32,&mut bytes);assert!(p.iter().all(|p|p.starts_with(b"IC")));receive(&mut net,id,p,&mut motion,&mut combat,&mut events);if net.status(id).unwrap().queued_events==0{break;}}assert_eq!(events.len(),12);assert_eq!(motion.states()[0].position.x,3);net.acknowledge(id,&held.unwrap()).unwrap();for _ in 0..1000{let p=poll(&mut net,&f,0,32,&mut bytes);receive(&mut net,id,p,&mut motion,&mut combat,&mut events);if drained(&net,id){break;}}assert_eq!(motion.sequence(),2);assert_eq!(motion.states(),f.visible(view()).unwrap());}

#[test]
fn motion_ack_during_partial_retry_finishes_frame_before_switching(){let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id,1);let mut bytes=Vec::new();let(mut motion,mut combat)=(Replica::new(10),CombatReplica::new_windowed(10));let mut events=Vec::new();let mut original=Vec::new();let mut ack=None;for _ in 0..1000{for p in poll(&mut net,&f,0,32,&mut bytes){if p.starts_with(b"IS"){ack=Some(motion.apply(&p).unwrap().acknowledgement());original=p;}else{receive(&mut net,id,vec![p],&mut motion,&mut combat,&mut events);}}if ack.is_some(){break;}}
 // The combat ACK may first trigger one empty prepare; wait for actual motion
 // progress before injecting an ACK specifically into its two-byte prefix.
 for _ in 0..4{assert!(poll(&mut net,&f,10,2,&mut bytes).is_empty());if !bytes.is_empty(){break;}}assert_eq!(bytes.len(),2);assert_eq!(net.acknowledge(id,&ack.unwrap()).unwrap(),AckDisposition::DeferredUntilFrameEnd);capture(&mut w,e,&mut c,&mut f,&mut net,id,2);let mut retried=None;for _ in 0..1000{let mut p=poll(&mut net,&f,10,32,&mut bytes);if !p.is_empty(){retried=Some(p.remove(0));break;}}assert_eq!(retried.unwrap(),original);assert_eq!(net.motion_status(id).unwrap().unwrap().pending_bytes,0);assert_eq!(net.acknowledge(id,&ack.unwrap()).unwrap(),AckDisposition::Duplicate);
}

#[test]
fn reconnect_discards_partial_transport_then_retries_and_new_stream_resets_motion(){let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id,1);let mut bytes=Vec::new();let(mut motion,mut combat)=(Replica::new(10),CombatReplica::new_windowed(10));let mut events=Vec::new();for _ in 0..1000{let p=poll(&mut net,&f,0,32,&mut bytes);receive(&mut net,id,p,&mut motion,&mut combat,&mut events);if net.motion_status(id).unwrap().unwrap().written_bytes>0{break;}}assert!(!bytes.is_empty());net.detach(id).unwrap();bytes.clear();net.resume(id).unwrap();let mut last_motion_ack=None;for _ in 0..1000{let p=poll(&mut net,&f,1,32,&mut bytes);for ack in receive(&mut net,id,p,&mut motion,&mut combat,&mut events){if ack.starts_with(b"IA"){last_motion_ack=Some(ack);}}if drained(&net,id){break;}}assert_eq!(motion.states(),f.visible(view()).unwrap());assert_eq!(events.len(),1);net.detach(id).unwrap();let stream=net.reset_replica(id).unwrap();assert_ne!(stream,10);assert_eq!(net.acknowledge(id,&last_motion_ack.unwrap()),Err(NetworkError::Sync(CombatSyncError::State(SyncError::WrongStream))));net.resume(id).unwrap();let mut fresh=Replica::new(stream);for _ in 0..1000{for p in poll(&mut net,&f,2,32,&mut bytes){assert!(p.starts_with(b"IS"));let r=fresh.apply(&p).unwrap();net.acknowledge(id,&r.acknowledgement()).unwrap();}if fresh.sequence()>0&&drained(&net,id){break;}}assert_eq!(fresh.states(),motion.states());}

#[test]
fn view_change_at_same_tick_refreshes_motion_and_motion_timeout_detaches_peer(){let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id,1);let(mut motion,mut combat)=(Replica::new(10),CombatReplica::new_windowed(10));let mut bytes=Vec::new();let mut events=Vec::new();for _ in 0..1000{let p=poll(&mut net,&f,0,32,&mut bytes);receive(&mut net,id,p,&mut motion,&mut combat,&mut events);if drained(&net,id)&&motion.sequence()>0{break;}}net.set_motion_view(id,ViewRect{min:GridPosition{x:100,y:100},max:GridPosition{x:200,y:200}}).unwrap();for _ in 0..1000{let p=poll(&mut net,&f,1,32,&mut bytes);if let Some(p)=p.first(){let r=motion.apply(p).unwrap();assert_eq!(r.sequence,2);assert!(motion.states().is_empty());break;}}let mut notices=Vec::new();net.poll_with_motion(101,&f,&mut NetworkBudget{work:1,bytes:32},&mut notices,|_,_|panic!("timeout before write")).unwrap();assert_eq!(notices[0].kind,NetworkNoticeKind::AckTimeout);assert!(!net.status(id).unwrap().attached);let retained=net.remove(id).unwrap();assert!(retained.motion.unwrap().pending_packet().is_some());}
